--
-- Déclencheurs `reservations`
--
DELIMITER $$
CREATE TRIGGER `after_reservation_created` AFTER INSERT ON `reservations` FOR EACH ROW BEGIN
      DECLARE v_espace_nom VARCHAR(255) DEFAULT '';                                                                                                                                                       
      SELECT nom INTO v_espace_nom FROM espaces WHERE id = NEW.espace_id LIMIT 1;            
                                                                                                                                                                                                          
      IF NEW.person_id IS NOT NULL THEN                                                                                                                                                                   
          VALUES (                                                                                                                                                                                        
              UUID(),                                                                        
              NEW.person_id,                                                                                                                                                                              
              'reservation',                                                                 
              'Nouvelle réservation',
              CONCAT('Votre réservation pour ', v_espace_nom, ' a été créée avec succès.'),                                                                                                               
              0,                                                                                                                                                                                          
              NOW()                                                                                                                                                                                       
          );                                                                                                                                                                                              
      END IF;                                                                                                                                                                                             
  END
$$
DELIMITER ;

