DELIMITER $$
CREATE TRIGGER `after_code_promo_used` AFTER INSERT ON `utilisations_codes_promo` FOR EACH ROW BEGIN
    UPDATE codes_promo
    SET utilisations_actuelles = utilisations_actuelles + 1
    WHERE id = NEW.code_promo_id;
END
$$
DELIMITER ;

