--
-- Structure de la vue `active_reservations`
--
DROP TABLE IF EXISTS `active_reservations`;

CREATE ALGORITHM=UNDEFINED DEFINER=`cofficed`@`localhost` SQL SECURITY DEFINER VIEW `active_reservations`  AS SELECT `r`.`id` AS `id`, `r`.`user_id` AS `user_id`, `r`.`contact_id` AS `contact_id`, `r`.`espace_id` AS `espace_id`, coalesce(`u`.`nom`,`t`.`nom`,'') AS `nom`, coalesce(`u`.`prenom`,`t`.`prenom`,'') AS `prenom`, coalesce(`u`.`email`,`t`.`email`,'') AS `email`, `e`.`nom` AS `espace_nom`, `e`.`type` AS `espace_type`, `r`.`date_debut` AS `date_debut`, `r`.`date_fin` AS `date_fin`, `r`.`statut` AS `statut`, `r`.`type_reservation` AS `type_reservation`, `r`.`montant_total` AS `montant_total`, `r`.`reduction` AS `reduction`, `r`.`participants` AS `participants`, `r`.`created_at` AS `created_at` FROM (((`reservations` `r` join `espaces` `e` on(`e`.`id` = `r`.`espace_id`)) left join `users` `u` on(`u`.`id` = `r`.`user_id`)) left join `tiers` `t` on(`t`.`id` = `r`.`contact_id`)) WHERE `r`.`statut` in ('confirmee','en_attente','en_cours') ;

-- --------------------------------------------------------

--
-- Structure de la vue `contact_history`
--
DROP TABLE IF EXISTS `contact_history`;

CREATE ALGORITHM=UNDEFINED DEFINER=`cofficed`@`localhost` SQL SECURITY DEFINER VIEW `contact_history`  AS SELECT `r`.`contact_id` AS `contact_id`, 'reservation' AS `type`, `r`.`id` AS `entity_id`, `r`.`created_at` AS `date`, concat(`e`.`nom`,' — ',`r`.`type_reservation`) AS `description`, `r`.`montant_total` AS `montant`, `r`.`statut` AS `statut` FROM (`reservations` `r` join `espaces` `e` on(`e`.`id` = `r`.`espace_id`)) WHERE `r`.`contact_id` is not nullunion allselect `d`.`contact_id` AS `contact_id`,'domiciliation' AS `type`,`d`.`id` AS `id`,`d`.`created_at` AS `created_at`,concat('Domiciliation — ',coalesce(`d`.`raison_sociale`,'N/A')) AS `CONCAT('Domiciliation — ', COALESCE(d.raison_sociale, 'N/A'))`,`d`.`montant_mensuel` AS `montant_mensuel`,`d`.`statut` AS `statut` from `domiciliations` `d` where `d`.`contact_id` is not null union all select `t`.`contact_id` AS `contact_id`,'transaction' AS `type`,`t`.`id` AS `id`,`t`.`created_at` AS `created_at`,coalesce(`t`.`description`,`t`.`type`) AS `COALESCE(t.description, t.type)`,`t`.`montant` AS `montant`,`t`.`statut` AS `statut` from `transactions` `t` where `t`.`contact_id` is not null union all select `au`.`contact_id` AS `contact_id`,'abonnement' AS `type`,`au`.`id` AS `id`,`au`.`created_at` AS `created_at`,concat('Abonnement — ',`ab`.`nom`) AS `CONCAT('Abonnement — ', ab.nom)`,NULL AS `NULL`,`au`.`statut` AS `statut` from (`abonnements_utilisateurs` `au` join `abonnements` `ab` on(`ab`.`id` = `au`.`abonnement_id`)) where `au`.`contact_id` is not null order by `date` desc  ;

-- --------------------------------------------------------

--
-- Structure de la vue `daily_stats`
--
DROP TABLE IF EXISTS `daily_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`cofficed`@`localhost` SQL SECURITY DEFINER VIEW `daily_stats`  AS SELECT cast(`reservations`.`created_at` as date) AS `date`, count(0) AS `total_reservations`, sum(`reservations`.`montant_total` - coalesce(`reservations`.`reduction`,0)) AS `revenue`, sum(case when `reservations`.`statut` = 'confirmee' then 1 else 0 end) AS `confirmed_count`, sum(case when `reservations`.`statut` = 'annulee' then 1 else 0 end) AS `cancelled_count`, avg(`reservations`.`montant_total` - coalesce(`reservations`.`reduction`,0)) AS `avg_amount`, sum(`reservations`.`participants`) AS `total_participants` FROM `reservations` GROUP BY cast(`reservations`.`created_at` as date) ;

